INSERT INTO content_revisions (id, item_id, data, status, note, created_by, created_at, submitted_at, reviewed_by, reviewed_at, published_at) VALUES ('199187296d3f8c81763493cca5', '1174f624ca586b49ac57517216', '{"name":"Energy & Utilities","note":"Field operations and asset monitoring","body":"Field operations and asset monitoring, where data arrives from equipment that was not designed to be on a network. Time-series ingestion, edge-to-cloud pipelines, and interfaces engineers can use with gloves on.","focus":["Asset and telemetry monitoring","Field service applications","Time-series data platforms"]}', 'published', 'Seeded from src/content', NULL, 1787060251274, NULL, NULL, NULL, 1787060251274);
